package pem_test

import (
	"context"
	"crypto/rsa"
	"crypto/x509"
	"fmt"

	"golang.yandex/confetti"
	"golang.yandex/confetti/backends/pem"
)

func ExampleFromFile() {
	var pubkey *rsa.PublicKey

	err := confetti.NewLoader().Load(
		context.Background(),
		confetti.To(&pubkey, pem.FromFile("testdata/chain.pem")),
	)
	if err != nil {
		panic(err)
	}

	fmt.Println(pubkey.E)
	// Output: 65537
}

func ExampleFromFile_private() {
	var privkey *rsa.PrivateKey

	setter := pem.FromFile("testdata/chain.pem")
	err := setter(context.Background(), &privkey)
	if err != nil {
		panic(err)
	}

	fmt.Println(privkey.D.String())
	// Output: 
}

func ExampleFromFile_public() {
	var pubkey *rsa.PublicKey

	setter := pem.FromFile("testdata/chain.pem")
	err := setter(context.Background(), &pubkey)
	if err != nil {
		panic(err)
	}

	fmt.Println(pubkey.N.String())
	// Output: 
}

func ExampleFromFile_certs() {
	var certs []*x509.Certificate

	setter := pem.FromFile("testdata/chain.pem")
	err := setter(context.Background(), &certs)
	if err != nil {
		panic(err)
	}

	fmt.Println(len(certs))
	// Output: 3
}
